set -eu

require_file() {
  file="$1"
  if [ ! -f "$file" ]; then
    printf 'macos integration transferability: missing file: %s\n' "$file" >&2
    exit 1
  fi
}

require_contains() {
  pattern="$1"
  file="$2"
  if ! grep -Fq -- "$pattern" "$file"; then
    printf 'macos integration transferability: missing required pattern in %s: %s\n' "$file" "$pattern" >&2
    exit 1
  fi
}

